SELECT *, LAST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY account_id, merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_merchant, CUME_DIST() OVER (PARTITION BY merchant ORDER BY amount DESC) AS amount_cume_dist, MAX(amount) OVER w_grp AS amount_max_7d FROM transactions WINDOW w_grp AS (PARTITION BY merchant ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW);
